set-variable.value:
@{
            		var raw = context.Response.Body.As<string>(preserveContent: true);
            		if (string.IsNullOrWhiteSpace(raw))
            		{
                        return new Newtonsoft.Json.Linq.JObject();
            		}
            		return Newtonsoft.Json.Linq.JObject.Parse(raw);
            	}

when.set-body:
@{
            		var body = (Newtonsoft.Json.Linq.JObject)context.Variables["webchatResponseBody"];
            		var sourceCitations = body["citations"] as Newtonsoft.Json.Linq.JArray ?? new Newtonsoft.Json.Linq.JArray();
            		var mappedCitations = new Newtonsoft.Json.Linq.JArray();

            		foreach (var citation in sourceCitations)
            		{
                        var title = (string)citation["title"] ?? (string)citation["source"] ?? "Source";
                        var url = (string)citation["url"] ?? (string)citation["source"] ?? string.Empty;
                        var content = (string)citation["content"] ?? string.Empty;

                        mappedCitations.Add(new Newtonsoft.Json.Linq.JObject
                        {
                        	["title"] = title,
                        	["url"] = url,
                        	["content"] = content
                        });
            		}

            		var transformed = new Newtonsoft.Json.Linq.JObject
            		{
                        ["answer"] = (string)body["answer"] ?? string.Empty,
                        ["citations"] = mappedCitations
            		};

            		return transformed.ToString(Newtonsoft.Json.Formatting.None);
            	}
